        float coreMaxZ = killMaxZ - ArenaCollision.SideBlastMargin;
        Vector3 coreCenter = new Vector3((coreMinX + coreMaxX) * 0.5f, prefabBounds.center.y, (coreMinZ + coreMaxZ) * 0.5f);
