// Last Stop "Mind the Gap" shell: closed solid volumes for Shared collision.
// X runs along the tracks (west -> east), Z north (+) across the gap, Y up.
string assetPath = "Assets/Stages/last_stop/LastStopCollision.asset";
string scenePath = "Assets/Stages/last_stop/last_stop.unity";
const float Kill = -10f;

var log = new System.Text.StringBuilder();

UnityEngine.Mesh Build(string name, System.Action<System.Collections.Generic.List<UnityEngine.Vector3>, System.Collections.Generic.List<UnityEngine.Vector3>, System.Collections.Generic.List<int>> fill)
{
    var v = new System.Collections.Generic.List<UnityEngine.Vector3>();
    var n = new System.Collections.Generic.List<UnityEngine.Vector3>();
    var t = new System.Collections.Generic.List<int>();
    fill(v, n, t);
    var mesh = new UnityEngine.Mesh { name = name };
    mesh.SetVertices(v);
    mesh.SetNormals(n);
    mesh.SetTriangles(t, 0);
    mesh.RecalculateBounds();
    return mesh;
}

// One flat-shaded triangle whose front face points along `outward`.
void Tri(System.Collections.Generic.List<UnityEngine.Vector3> v, System.Collections.Generic.List<UnityEngine.Vector3> n, System.Collections.Generic.List<int> t,
    UnityEngine.Vector3 a, UnityEngine.Vector3 b, UnityEngine.Vector3 c, UnityEngine.Vector3 outward)
{
    UnityEngine.Vector3 cross = UnityEngine.Vector3.Cross(b - a, c - a);
    if (UnityEngine.Vector3.Dot(cross, outward) < 0f) { var tmp = b; b = c; c = tmp; }
    int i = v.Count;
    v.Add(a); v.Add(b); v.Add(c);
    UnityEngine.Vector3 nn = outward.normalized;
    n.Add(nn); n.Add(nn); n.Add(nn);
    t.Add(i); t.Add(i + 1); t.Add(i + 2);
}

// Vertical prism over a convex XZ footprint (any winding), from yBottom to yTop.
void Prism(System.Collections.Generic.List<UnityEngine.Vector3> v, System.Collections.Generic.List<UnityEngine.Vector3> n, System.Collections.Generic.List<int> t,
    UnityEngine.Vector2[] poly, float yBottom, float yTop, bool top, bool bottom, int skipSide)
{
    UnityEngine.Vector2 centroid = UnityEngine.Vector2.zero;
    foreach (var p in poly) centroid += p;
    centroid /= poly.Length;
    for (int i = 1; i + 1 < poly.Length; i++)
    {
        var a = poly[0]; var b = poly[i]; var c = poly[i + 1];
        if (top) Tri(v, n, t, new UnityEngine.Vector3(a.x, yTop, a.y), new UnityEngine.Vector3(b.x, yTop, b.y), new UnityEngine.Vector3(c.x, yTop, c.y), UnityEngine.Vector3.up);
        if (bottom) Tri(v, n, t, new UnityEngine.Vector3(a.x, yBottom, a.y), new UnityEngine.Vector3(b.x, yBottom, b.y), new UnityEngine.Vector3(c.x, yBottom, c.y), UnityEngine.Vector3.down);
    }
    for (int i = 0; i < poly.Length; i++)
    {
        if (i == skipSide) continue;
        var a = poly[i]; var b = poly[(i + 1) % poly.Length];
        var mid = (a + b) * 0.5f;
        var edge = b - a;
        var outward2 = new UnityEngine.Vector2(edge.y, -edge.x);
        if (UnityEngine.Vector2.Dot(outward2, mid - centroid) < 0f) outward2 = -outward2;
        var outward = new UnityEngine.Vector3(outward2.x, 0f, outward2.y);
        var a0 = new UnityEngine.Vector3(a.x, yBottom, a.y); var a1 = new UnityEngine.Vector3(a.x, yTop, a.y);
        var b0 = new UnityEngine.Vector3(b.x, yBottom, b.y); var b1 = new UnityEngine.Vector3(b.x, yTop, b.y);
        Tri(v, n, t, a0, b0, b1, outward);
        Tri(v, n, t, a0, b1, a1, outward);
    }
}

UnityEngine.Vector2[] Rect(float x0, float x1, float z0, float z1) => new[]
{
    new UnityEngine.Vector2(x0, z0), new UnityEngine.Vector2(x1, z0),
    new UnityEngine.Vector2(x1, z1), new UnityEngine.Vector2(x0, z1)
};

// Main floor: island platform, square along the gap, chamfered on its outer corners.
var platformPoly = new[]
{
    new UnityEngine.Vector2(-16f, 0f), new UnityEngine.Vector2(16f, 0f),
    new UnityEngine.Vector2(16f, -9.5f), new UnityEngine.Vector2(13.5f, -12f),
    new UnityEngine.Vector2(-13.5f, -12f), new UnityEngine.Vector2(-16f, -9.5f)
};
// Portal Rock: the tunnel buttress at the train's east end (L2 perch).
var rockPoly = new[]
{
    new UnityEngine.Vector2(16f, 2.5f), new UnityEngine.Vector2(19.5f, 2f),
    new UnityEngine.Vector2(22f, 3.8f), new UnityEngine.Vector2(22.5f, 7.8f),
    new UnityEngine.Vector2(20.2f, 10.3f), new UnityEngine.Vector2(16f, 9.2f)
};

var meshes = new System.Collections.Generic.Dictionary<string, UnityEngine.Mesh>
{
    ["Platform"] = Build("LastStopPlatformCollision", (v, n, t) => Prism(v, n, t, platformPoly, Kill, 0f, true, true, -1)),
    // Carriages + saddle-tank locomotive share one 4-wide body, extended 0.5 into Portal Rock.
    ["Train"] = Build("LastStopTrainCollision", (v, n, t) => Prism(v, n, t, Rect(-18f, 16.5f, 3f, 7f), Kill, 1.8f, true, true, -1)),
    ["Cab"] = Build("LastStopCabCollision", (v, n, t) => Prism(v, n, t, Rect(-11f, -8f, 3f, 7f), 1.8f, 2.7f, true, false, -1)),
    ["Chimney"] = Build("LastStopChimneyCollision", (v, n, t) => Prism(v, n, t, Rect(-17.2f, -16.2f, 4.5f, 5.5f), 1.8f, 2.8f, true, false, -1)),
    ["BufferStop"] = Build("LastStopBufferStopCollision", (v, n, t) => Prism(v, n, t, Rect(-18.8f, -18f, 3f, 7f), Kill, 0.4f, true, true, -1)),
    ["PortalRock"] = Build("LastStopPortalRockCollision", (v, n, t) => Prism(v, n, t, rockPoly, Kill, 3.8f, true, true, -1)),
};

// Persist: first mesh is the main asset, the rest are sub-assets.
if (UnityEditor.AssetDatabase.LoadMainAssetAtPath(assetPath) != null)
    UnityEditor.AssetDatabase.DeleteAsset(assetPath);
bool first = true;
foreach (var kv in meshes)
{
    if (first) { UnityEditor.AssetDatabase.CreateAsset(kv.Value, assetPath); first = false; }
    else UnityEditor.AssetDatabase.AddObjectToAsset(kv.Value, assetPath);
}
UnityEditor.AssetDatabase.SaveAssets();
UnityEditor.AssetDatabase.ImportAsset(assetPath, UnityEditor.ImportAssetOptions.ForceUpdate);
var saved = System.Linq.Enumerable.ToDictionary(
    System.Linq.Enumerable.OfType<UnityEngine.Mesh>(UnityEditor.AssetDatabase.LoadAllAssetsAtPath(assetPath)), m => m.name);
int triCount = 0;
foreach (var m in saved.Values) triCount += m.triangles.Length / 3;
log.Append("meshes=" + saved.Count + " tris=" + triCount + "; ");

// Rewire the authoring scene additively so the open Frontend stays untouched.
var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene(scenePath, UnityEditor.SceneManagement.OpenSceneMode.Additive);
try
{
    var root = System.Linq.Enumerable.First(scene.GetRootGameObjects(), g => g.name == "Stage_last_stop");
    var geometry = root.transform.Find("GameplayGeometry");
    var old = new System.Collections.Generic.List<UnityEngine.GameObject>();
    foreach (UnityEngine.Transform child in geometry) old.Add(child.gameObject);
    UnityEngine.Material sharedMat = null;
    foreach (var go in old)
    {
        var r = go.GetComponent<UnityEngine.MeshRenderer>();
        if (r != null && sharedMat == null) sharedMat = r.sharedMaterial;
        UnityEngine.Object.DestroyImmediate(go);
    }
    string[] order = { "Platform", "Train", "Cab", "Chimney", "BufferStop", "PortalRock" };
    string[] meshNames = { "LastStopPlatformCollision", "LastStopTrainCollision", "LastStopCabCollision", "LastStopChimneyCollision", "LastStopBufferStopCollision", "LastStopPortalRockCollision" };
    for (int i = 0; i < order.Length; i++)
    {
        var go = new UnityEngine.GameObject(order[i]);
        UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go, scene);
        go.transform.SetParent(geometry, false);
        go.AddComponent<UnityEngine.MeshFilter>().sharedMesh = saved[meshNames[i]];
        var mr = go.AddComponent<UnityEngine.MeshRenderer>();
        if (sharedMat != null) mr.sharedMaterial = sharedMat;
        go.isStatic = true;
    }

    // Four platform spawns, two rows either side of the platform centre line (Z=-6),
    // each facing a point just south of the gap so the opening view shows the train.
    var spawns = root.transform.Find("SpawnPoints");
    var spawnPos = new System.Collections.Generic.Dictionary<string, UnityEngine.Vector2>
    {
        ["Spawn_01"] = new UnityEngine.Vector2(-7f, -3.5f),
        ["Spawn_02"] = new UnityEngine.Vector2(7f, -8.5f),
        ["Spawn_03"] = new UnityEngine.Vector2(-7f, -8.5f),
        ["Spawn_04"] = new UnityEngine.Vector2(7f, -3.5f),
    };
    var focus = new UnityEngine.Vector2(0f, -2f);
    foreach (var kv in spawnPos)
    {
        var marker = spawns.Find(kv.Key);
        marker.position = new UnityEngine.Vector3(kv.Value.x, 0.85f, kv.Value.y);
        var dir = focus - kv.Value;
        float yaw = UnityEngine.Mathf.Atan2(dir.x, dir.y) * UnityEngine.Mathf.Rad2Deg;
        marker.rotation = UnityEngine.Quaternion.Euler(0f, yaw, 0f);
        log.Append(kv.Key + " yaw=" + yaw.ToString("F1") + " ");
    }
    var kill = root.transform.Find("AuthoringAids/KillPlane");
    kill.position = new UnityEngine.Vector3(0f, Kill, 0f);

    UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
    bool ok = UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
    log.Append("; sceneSaved=" + ok);
}
finally
{
    UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene, true);
}
return log.ToString();

