using System;
using System.Collections.Generic;
using SlopArena.Shared;

static class P
{
    static ArenaDefinition arena;
    static InputState In(float mx = 0, float my = 0, bool jump = false, bool held = false)
        => new InputState { MoveX = mx, MoveY = my, Jump = jump, JumpHeld = held };

    static CharacterState Start(CharacterDefinition def, float x, float z, float floorY)
    {
        return new CharacterState { EntityId = 1, PX = x, PY = floorY + def.CapsuleHeight * 0.5f, PZ = z,
            State = ActionState.Idle, IsGrounded = true, JumpsLeft = 2, AirDodgesLeft = 1 };
    }

    // Run toward (dx,dz); jump when the trigger fires; optional air jump at apex; stop steering once past stopAxis.
    static (CharacterState s, int tick) Route(CharacterDefinition def, CharacterState st, float dx, float dz,
        Func<CharacterState, bool> jumpWhen, bool airJump, Func<CharacterState, bool> stopSteer, int maxTicks = 240)
    {
        var sim = new ServerSimulation(arena);
        sim.RegisterEntity(1, def, st);
        var inputs = new Dictionary<ulong, InputState>();
        int jumpTick = -1, airTick = -1; bool airborne = false;
        for (int t = 0; t < maxTicks; t++)
        {
            var b = sim.GetState(1);
            bool press = jumpTick < 0 && jumpWhen(b);
            if (press) jumpTick = t;
            bool airPress = airJump && jumpTick >= 0 && airTick < 0 && t - jumpTick > 6 && !b.IsGrounded && b.VY <= 0f;
            if (airPress) airTick = t;
            bool steer = !stopSteer(b);
            bool held = (jumpTick >= 0 && t - jumpTick < 12) || (airTick >= 0 && t - airTick < 12);
            inputs[1] = In(steer ? dx : 0, steer ? dz : 0, press || airPress, held);
            sim.Tick(inputs);
            var c = sim.GetState(1);
            if (c.Deaths > 0) return (c, t);
            airborne |= jumpTick >= 0 && !c.IsGrounded;
            if (airborne && c.IsGrounded) return (c, t);
        }
        return (sim.GetState(1), maxTicks);
    }

    static string Where(CharacterDefinition def, CharacterState s)
