// Last Stop "Mind the Gap" gray-box blockout: massing only, one study light, no Colliders.
// World frame: X along the tracks (west -> east), Z north, Y up. Blast corridor:
// X [-28.8, 32.5], Z [-22, 20.3], Y [-10, 23.7]; background stays outside it or below Y=-10.
string prefabPath = "Assets/Resources/Stages/last_stop.prefab";
var log = new System.Text.StringBuilder();

var tempScene = UnityEditor.SceneManagement.EditorSceneManager.NewScene(
    UnityEditor.SceneManagement.NewSceneSetup.EmptyScene, UnityEditor.SceneManagement.NewSceneMode.Additive);
var previousActive = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
UnityEngine.SceneManagement.SceneManager.SetActiveScene(tempScene);
var generated = new System.Collections.Generic.List<UnityEngine.Object>();
try
{
    var shader = UnityEngine.Shader.Find("Universal Render Pipeline/Lit");
    UnityEngine.Material Mat(string name, float g, float smooth = 0.1f)
    {
        var m = new UnityEngine.Material(shader) { name = name };
        m.SetColor("_BaseColor", new UnityEngine.Color(g, g, g, 1f));
        m.SetFloat("_Smoothness", smooth);
        generated.Add(m);
        return m;
    }
    var gray = Mat("DesignGray", 0.6f);
    var grayDark = Mat("DesignGrayDark", 0.38f);
    var grayLight = Mat("DesignGrayLight", 0.82f);
    var cloud = Mat("DesignCloud", 0.92f);

    UnityEngine.GameObject Node(string name, UnityEngine.Transform parent)
    {
        var go = new UnityEngine.GameObject(name);
        go.transform.SetParent(parent, false);
        return go;
    }
    UnityEngine.GameObject Prim(UnityEngine.PrimitiveType type, string name, UnityEngine.Transform parent,
        UnityEngine.Vector3 pos, UnityEngine.Vector3 scale, UnityEngine.Material mat, UnityEngine.Vector3 euler = default)
    {
        var go = UnityEngine.GameObject.CreatePrimitive(type);
        UnityEngine.Object.DestroyImmediate(go.GetComponent<UnityEngine.Collider>());
        go.name = name;
        go.transform.SetParent(parent, false);
        go.transform.localPosition = pos;
        go.transform.localRotation = UnityEngine.Quaternion.Euler(euler);
        go.transform.localScale = scale;
        go.GetComponent<UnityEngine.MeshRenderer>().sharedMaterial = mat;
        return go;
    }
    // Box from min/max corners.
    UnityEngine.GameObject Box(string name, UnityEngine.Transform parent, UnityEngine.Vector3 min, UnityEngine.Vector3 max, UnityEngine.Material mat)
        => Prim(UnityEngine.PrimitiveType.Cube, name, parent, (min + max) * 0.5f, max - min, mat);

    // N-sided cone/frustum mesh (base at y=0, apex at y=1), persisted as a prefab sub-asset.
    UnityEngine.Mesh coneMesh = null;
    UnityEngine.Mesh Cone()
    {
        if (coneMesh != null) return coneMesh;
        int sides = 7;
        var v = new System.Collections.Generic.List<UnityEngine.Vector3>();
        var t = new System.Collections.Generic.List<int>();
        for (int i = 0; i < sides; i++)
        {
            float a0 = i * UnityEngine.Mathf.PI * 2f / sides, a1 = (i + 1) * UnityEngine.Mathf.PI * 2f / sides;
            var p0 = new UnityEngine.Vector3(UnityEngine.Mathf.Sin(a0) * 0.5f, 0f, UnityEngine.Mathf.Cos(a0) * 0.5f);
            var p1 = new UnityEngine.Vector3(UnityEngine.Mathf.Sin(a1) * 0.5f, 0f, UnityEngine.Mathf.Cos(a1) * 0.5f);
            int b = v.Count;
            v.Add(p0); v.Add(new UnityEngine.Vector3(0f, 1f, 0f)); v.Add(p1);
            t.Add(b); t.Add(b + 1); t.Add(b + 2);
        }
        coneMesh = new UnityEngine.Mesh { name = "DesignCone" };
        coneMesh.SetVertices(v); coneMesh.SetTriangles(t, 0);
        coneMesh.RecalculateNormals(); coneMesh.RecalculateBounds();
        generated.Add(coneMesh);
        return coneMesh;
    }
    UnityEngine.GameObject Peak(string name, UnityEngine.Transform parent, float x, float z, float baseY, float topY, float radius, UnityEngine.Material mat, float yaw = 0f)
    {
        var go = Node(name, parent);
        go.transform.localPosition = new UnityEngine.Vector3(x, baseY, z);
        go.transform.localRotation = UnityEngine.Quaternion.Euler(0f, yaw, 0f);
        go.transform.localScale = new UnityEngine.Vector3(radius * 2f, topY - baseY, radius * 1.6f);
        go.AddComponent<UnityEngine.MeshFilter>().sharedMesh = Cone();
        go.AddComponent<UnityEngine.MeshRenderer>().sharedMaterial = mat;
        return go;
    }

    var root = new UnityEngine.GameObject("last_stop");

    // ── Shell: exact collision volumes (named Shell* so design capture frames the fight). ──
    var shell = Node("Shell", root.transform);
    foreach (var part in new[] { "Platform", "Train", "Cab", "Chimney", "BufferStop", "PortalRock" })
    {
        var mesh = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>("Assets/Stages/last_stop/Collision/LastStop" + part + ".asset");
        var go = Node("Shell" + part, shell.transform);
        go.AddComponent<UnityEngine.MeshFilter>().sharedMesh = mesh;
        go.AddComponent<UnityEngine.MeshRenderer>().sharedMaterial = part == "Platform" ? grayLight : gray;
    }

    // ── Train massing: bodies continue below the platform into the gap; bogies + rails beneath. ──
    var train = Node("TrainMassing", root.transform);
    // Carriage window band (dark) on the gap side reads the train from the platform.
    Box("Carriage1WindowBand", train.transform, new UnityEngine.Vector3(-6.4f, 0.45f, 2.97f), new UnityEngine.Vector3(3.4f, 1.35f, 3.0f), grayDark);
    Box("Carriage2WindowBand", train.transform, new UnityEngine.Vector3(4.1f, 0.45f, 2.97f), new UnityEngine.Vector3(15.9f, 1.35f, 3.0f), grayDark);
    Box("GangwayShadow", train.transform, new UnityEngine.Vector3(3.4f, -1.4f, 2.96f), new UnityEngine.Vector3(4.1f, 1.8f, 3.0f), grayDark);
    Box("LocoTankShadow", train.transform, new UnityEngine.Vector3(-7.4f, -1.4f, 2.96f), new UnityEngine.Vector3(-6.4f, 1.8f, 3.0f), grayDark);
    for (int i = 0; i < 6; i++)
    {
        float bx = -15f + i * 5.6f;
        Box("Bogie" + i, train.transform, new UnityEngine.Vector3(bx - 1.2f, -2.6f, 2.98f), new UnityEngine.Vector3(bx + 1.2f, -1.4f, 3.0f), grayDark);
    }
    Box("TrackBedSouthEdge", train.transform, new UnityEngine.Vector3(-18.8f, -2.9f, 2.96f), new UnityEngine.Vector3(16f, -2.6f, 3.0f), grayLight);
    Prim(UnityEngine.PrimitiveType.Cylinder, "ChimneyCap", train.transform, new UnityEngine.Vector3(-16.7f, 2.85f, 5f), new UnityEngine.Vector3(1.25f, 0.06f, 1.25f), grayDark);
    Prim(UnityEngine.PrimitiveType.Sphere, "EndOfLineLamp", train.transform, new UnityEngine.Vector3(-18.4f, 0.6f, 5f), new UnityEngine.Vector3(0.35f, 0.35f, 0.35f), grayLight);
    // Tunnel portal frame on Portal Rock's west face and the station facade on its south face.
    Box("PortalArchDark", train.transform, new UnityEngine.Vector3(15.97f, -2.6f, 3.2f), new UnityEngine.Vector3(16.0f, 2.3f, 6.8f), grayDark);
    Box("StationFacadeWindows", train.transform, new UnityEngine.Vector3(16.8f, -0.4f, 2.32f), new UnityEngine.Vector3(19.0f, 1.6f, 2.38f), grayDark);
    Box("LastStopSignBoard", train.transform, new UnityEngine.Vector3(16.6f, 2.2f, 2.26f), new UnityEngine.Vector3(19.4f, 3.2f, 2.34f), grayLight);

    // ── Pinnacle base: below the lower blast plane the split rock widens into one massif. ──
    var pinnacle = Node("PinnacleBase", root.transform);
    Box("SouthPillarFlare", pinnacle.transform, new UnityEngine.Vector3(-18f, -22f, -14f), new UnityEngine.Vector3(18f, -10f, 0f), gray);
    Box("NorthPillarFlare", pinnacle.transform, new UnityEngine.Vector3(-20f, -22f, 3f), new UnityEngine.Vector3(24f, -10f, 12f), gray);
    Box("SharedRoot", pinnacle.transform, new UnityEngine.Vector3(-22f, -40f, -16f), new UnityEngine.Vector3(26f, -22f, 14f), gray);

    // ── Cloud sea just below the blast plane; the world below is hidden. ──
    Prim(UnityEngine.PrimitiveType.Cube, "CloudSea", root.transform, new UnityEngine.Vector3(0f, -16.5f, 0f), new UnityEngine.Vector3(900f, 1f, 900f), cloud);

    // ── Surrounding world, all outside the corridor ──
    var world = Node("World", root.transform);
    // Near spires (depth layer one): rock needles rising from the clouds.
    Peak("SpireWest", world.transform, -50f, -6f, -18f, 8f, 9f, gray, 20f);
    Peak("SpireNorthEast", world.transform, 56f, 34f, -18f, 14f, 11f, gray, 70f);
    Peak("SpireSouth", world.transform, -18f, -58f, -18f, -1f, 10f, gray, 40f);
    Peak("SpireSouthEast", world.transform, 40f, -54f, -18f, 5f, 8f, gray, 10f);
    // Hero peak: centre background from the default view (camera south, looking north).
    Peak("HeroHorn", world.transform, 18f, 290f, -20f, 125f, 70f, grayLight, 15f);
    // Supporting range: uneven heights and gaps, quieter than the Horn.
    float[,] range =
    {
        { -170f, 220f, 55f, 60f }, { -250f, 120f, 40f, 70f }, { -260f, -60f, 48f, 75f },
        { -180f, -230f, 35f, 60f }, { 10f, -300f, 62f, 80f }, { 190f, -220f, 42f, 70f },
        { 280f, -40f, 58f, 80f }, { 260f, 150f, 45f, 65f }, { 150f, 260f, 70f, 70f },
        { -90f, 300f, 66f, 60f }
    };
    for (int i = 0; i < range.GetLength(0); i++)
        Peak("Range" + i, world.transform, range[i, 0], range[i, 1], -20f, range[i, 2], range[i, 3], gray, i * 37f);

    // Viaduct (left background from the default view): curved arches between two cliffs.
    var viaduct = Node("Viaduct", world.transform);
    var a = new UnityEngine.Vector3(-150f, 0f, 70f);
    var b = new UnityEngine.Vector3(-60f, 0f, 150f);
    var bend = new UnityEngine.Vector3(-85f, 0f, 75f);
    int arches = 9;
    for (int i = 0; i <= arches; i++)
    {
        float tt = i / (float)arches;
        var p = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.Lerp(a, bend, tt), UnityEngine.Vector3.Lerp(bend, b, tt), tt);
        var pn = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.Lerp(a, bend, tt + 0.01f), UnityEngine.Vector3.Lerp(bend, b, tt + 0.01f), tt + 0.01f);
        float yaw = UnityEngine.Mathf.Atan2(pn.x - p.x, pn.z - p.z) * UnityEngine.Mathf.Rad2Deg;
        Prim(UnityEngine.PrimitiveType.Cube, "Pier" + i, viaduct.transform, new UnityEngine.Vector3(p.x, -16f, p.z), new UnityEngine.Vector3(3f, 24f, 4f), gray, new UnityEngine.Vector3(0f, yaw, 0f));
        if (i < arches)
        {
            float t2 = (i + 0.5f) / arches;
            var q = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.Lerp(a, bend, t2), UnityEngine.Vector3.Lerp(bend, b, t2), t2);
            Prim(UnityEngine.PrimitiveType.Cube, "Deck" + i, viaduct.transform, new UnityEngine.Vector3(q.x, -3.5f, q.z), new UnityEngine.Vector3(4.2f, 1.6f, 12.5f), grayLight, new UnityEngine.Vector3(0f, yaw, 0f));
        }
    }
    Peak("ViaductCliffWest", world.transform, -168f, 62f, -20f, 30f, 30f, gray, 0f);
    Peak("ViaductCliffNorth", world.transform, -52f, 170f, -20f, 38f, 34f, gray, 30f);
    // Hamlet ridge (right background): a shoulder above the clouds with chalet volumes.
    var hamlet = Node("HamletRidge", world.transform);
    Prim(UnityEngine.PrimitiveType.Cube, "Ridge", hamlet.transform, new UnityEngine.Vector3(115f, -14f, 125f), new UnityEngine.Vector3(70f, 16f, 30f), gray, new UnityEngine.Vector3(0f, -35f, 8f));
    for (int i = 0; i < 5; i++)
        Box("Chalet" + i, hamlet.transform, new UnityEngine.Vector3(95f + i * 9f, -6f, 135f - i * 6.5f), new UnityEngine.Vector3(101f + i * 9f, -1f, 140f - i * 6.5f), grayLight);

    // One study light (low western sun) and the stage atmosphere.
    var sun = Node("StudySun", root.transform);
    sun.transform.localRotation = UnityEngine.Quaternion.Euler(18f, 100f, 0f);
    var light = sun.AddComponent<UnityEngine.Light>();
    light.type = UnityEngine.LightType.Directional;
    light.intensity = 1.1f;
    light.shadows = UnityEngine.LightShadows.Soft;

    // Persist: recreate the prefab, then attach generated materials/meshes as sub-assets.
    if (UnityEditor.AssetDatabase.LoadMainAssetAtPath(prefabPath) != null)
        UnityEditor.AssetDatabase.DeleteAsset(prefabPath);
    var saved = UnityEditor.PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
    foreach (var obj in generated) UnityEditor.AssetDatabase.AddObjectToAsset(obj, prefabPath);
    UnityEditor.AssetDatabase.SaveAssets();
    // Re-save so renderer references resolve to the persisted sub-assets.
    var contents = UnityEditor.PrefabUtility.LoadPrefabContents(prefabPath);
    UnityEditor.PrefabUtility.SaveAsPrefabAsset(contents, prefabPath);
    UnityEditor.PrefabUtility.UnloadPrefabContents(contents);
    UnityEngine.Object.DestroyImmediate(root);

    int renderers = 0, colliders = 0;
    var check = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(prefabPath);
    renderers = check.GetComponentsInChildren<UnityEngine.Renderer>(true).Length;
    colliders = check.GetComponentsInChildren<UnityEngine.Collider>(true).Length;
    int missing = 0;
    foreach (var r in check.GetComponentsInChildren<UnityEngine.MeshRenderer>(true))
    {
        if (r.sharedMaterial == null) missing++;
        var mf = r.GetComponent<UnityEngine.MeshFilter>();
        if (mf == null || mf.sharedMesh == null) missing++;
    }
    log.Append("prefab=" + (saved != null) + " renderers=" + renderers + " colliders=" + colliders + " missingRefs=" + missing);
}
finally
{
    UnityEngine.SceneManagement.SceneManager.SetActiveScene(previousActive);
    UnityEditor.SceneManagement.EditorSceneManager.CloseScene(tempScene, true);
}
return log.ToString();

