        """Box whose two top edges running along `axis` ('x' or 'z') are rounded by `rad`.
        mats: optional {'side','top','end'} material overrides."""
        x0, y0, z0 = mn; x1, y1, z1 = mx
        w0, w1, l0, l1 = (z0, z1, x0, x1) if axis == 'x' else (x0, x1, z0, z1)
        prof = [(w0, y0)]
        for i in range(seg + 1):
            ang = math.pi - i / seg * (math.pi / 2)
            prof.append((w0 + rad + math.cos(ang) * rad, y1 - rad + math.sin(ang) * rad))
        for i in range(seg + 1):
            ang = math.pi / 2 - i / seg * (math.pi / 2)
            prof.append((w1 - rad + math.cos(ang) * rad, y1 - rad + math.sin(ang) * rad))
        prof.append((w1, y0))

        def P(w, y, l):
            return (l, y, w) if axis == 'x' else (w, y, l)

        def O(ow, oy):
            return (0, oy, ow) if axis == 'x' else (ow, oy, 0)
        mats = mats or {}
        side = mats.get('side', mat); topm = mats.get('top', mat); endm = mats.get('end', mat)
        cw, cy = (w0 + w1) / 2, y0 + (y1 - y0) * 0.3
        n = len(prof)
        for i in range(n - 1):
            a = prof[i]; b = prof[i + 1]
            if abs(a[0] - b[0]) < 1e-9 and abs(a[1] - b[1]) < 1e-9:
