// Last Stop: textures, URP materials, and FBX material remaps (all stage-owned, original).
string root = "Assets/Stages/last_stop";
string texDir = root + "/Textures";
string matDir = root + "/Materials";
string artDir = root + "/Art";
var log = new System.Text.StringBuilder();
if (!UnityEditor.AssetDatabase.IsValidFolder(matDir)) UnityEditor.AssetDatabase.CreateFolder(root, "Materials");
UnityEditor.AssetDatabase.Refresh();

// ── Texture import settings ──
foreach (var guid in UnityEditor.AssetDatabase.FindAssets("t:Texture2D", new[] { texDir }))
{
    string path = UnityEditor.AssetDatabase.GUIDToAssetPath(guid);
    var ti = (UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(path);
    string name = System.IO.Path.GetFileNameWithoutExtension(path);
    bool alpha = name == "LastStopCloudTops" || name == "LastStopSoftDot" || name == "LastStopClockFace" || name == "LastStopMoon";
    ti.textureType = UnityEditor.TextureImporterType.Default;
    ti.sRGBTexture = true;
    ti.alphaSource = alpha ? UnityEditor.TextureImporterAlphaSource.FromInput : UnityEditor.TextureImporterAlphaSource.None;
    ti.alphaIsTransparency = alpha;
    ti.mipmapEnabled = true;
    ti.wrapMode = UnityEngine.TextureWrapMode.Repeat;
    if (name == "LastStopSky") { ti.wrapModeU = UnityEngine.TextureWrapMode.Repeat; ti.wrapModeV = UnityEngine.TextureWrapMode.Clamp; ti.mipmapEnabled = false; }
    if (name == "LastStopClockFace" || name == "LastStopMoon" || name == "LastStopSoftDot") ti.wrapMode = UnityEngine.TextureWrapMode.Clamp;
    ti.filterMode = UnityEngine.FilterMode.Trilinear;
    ti.anisoLevel = 4;
    ti.maxTextureSize = 2048;
    ti.textureCompression = UnityEditor.TextureImporterCompression.CompressedHQ;
    ti.SaveAndReimport();
}
UnityEngine.Texture2D Tex(string n) => UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture2D>(texDir + "/" + n + ".png");

var lit = UnityEngine.Shader.Find("Universal Render Pipeline/Lit");
var unlit = UnityEngine.Shader.Find("Universal Render Pipeline/Unlit");
var particlesUnlit = UnityEngine.Shader.Find("Universal Render Pipeline/Particles/Unlit");
var mats = new System.Collections.Generic.Dictionary<string, UnityEngine.Material>();

UnityEngine.Material Mat(string name, UnityEngine.Shader shader)
{
    string path = matDir + "/" + name + ".mat";
    var m = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>(path);
    if (m == null)
    {
        m = new UnityEngine.Material(shader) { name = name };
        UnityEditor.AssetDatabase.CreateAsset(m, path);
    }
    m.shader = shader;
    mats[name] = m;
    return m;
}
void Opaque(UnityEngine.Material m, float r, float g, float b, float smooth = 0.2f, float metal = 0f, UnityEngine.Texture2D tex = null)
{
    m.SetColor("_BaseColor", new UnityEngine.Color(r, g, b, 1f));
    if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", smooth);
    if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", metal);
    m.SetTexture("_BaseMap", tex);
    m.SetFloat("_Surface", 0f);
    m.SetOverrideTag("RenderType", "Opaque");
    m.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.One);
    m.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.Zero);
    m.SetFloat("_ZWrite", 1f);
    m.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
    m.renderQueue = -1;
}
void Emissive(UnityEngine.Material m, float r, float g, float b, float intensity)
{
    m.EnableKeyword("_EMISSION");
    m.SetColor("_EmissionColor", new UnityEngine.Color(r, g, b, 1f) * intensity);
    m.globalIlluminationFlags = UnityEngine.MaterialGlobalIlluminationFlags.None;
}
void Transparent(UnityEngine.Material m)
{
    m.SetFloat("_Surface", 1f);
    m.SetFloat("_Blend", 0f);
    m.SetOverrideTag("RenderType", "Transparent");
    m.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.SrcAlpha);
    m.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
    if (m.HasProperty("_SrcBlendAlpha")) m.SetFloat("_SrcBlendAlpha", (float)UnityEngine.Rendering.BlendMode.One);
    if (m.HasProperty("_DstBlendAlpha")) m.SetFloat("_DstBlendAlpha", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
    m.SetFloat("_ZWrite", 0f);
    m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
    m.DisableKeyword("_ALPHAPREMULTIPLY_ON");
    m.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
}
void Cutout(UnityEngine.Material m, float cutoff)
{
    m.SetFloat("_AlphaClip", 1f);
    m.SetFloat("_Cutoff", cutoff);
    m.EnableKeyword("_ALPHATEST_ON");
    m.SetOverrideTag("RenderType", "TransparentCutout");
    m.renderQueue = (int)UnityEngine.Rendering.RenderQueue.AlphaTest;
}

