var fire = Mat("LS_FireGlow", lit); Opaque(fire, 1f, 0.45f, 0.1f, 0.2f); Emissive(fire, 1f, 0.36f, 0.06f, 3.5f);
var red = Mat("LS_LampRed", lit); Opaque(red, 1f, 0.12f, 0.08f, 0.6f); Emissive(red, 1f, 0.07f, 0.04f, 5f);
var warm = Mat("LS_LampWarm", lit); Opaque(warm, 1f, 0.92f, 0.75f, 0.6f); Emissive(warm, 1f, 0.82f, 0.55f, 3.2f);
Opaque(Mat("LS_TunnelDark", unlit), 0.008f, 0.01f, 0.018f);
