var mist = Mat("LS_Mist", unlit); Opaque(mist, 0.98f, 0.93f, 1f, 0f, 0f, Tex("LastStopCloudTops")); Transparent(mist);
mist.SetColor("_BaseColor", new UnityEngine.Color(0.98f, 0.93f, 1f, 0.5f));
