var assets = UnityEditor.AssetDatabase.LoadAllAssetsAtPath("Assets/Stages/last_stop/Art/LastStopTrain.fbx");
var sb = new System.Text.StringBuilder();
foreach (var a in assets)
{
    var mesh = a as UnityEngine.Mesh;
    if (mesh == null || (mesh.name != "CarriageWindows" && mesh.name != "Carriages")) continue;
    var v = mesh.vertices; var n = mesh.normals; var t = mesh.triangles;
    int northFront = 0, northBack = 0, southFront = 0, southBack = 0, normalMismatch = 0;
    for (int i = 0; i < t.Length; i += 3)
    {
        var A = v[t[i]]; var B = v[t[i + 1]]; var C = v[t[i + 2]];
        var w = UnityEngine.Vector3.Cross(B - A, C - A).normalized;
        var nn = (n[t[i]] + n[t[i + 1]] + n[t[i + 2]]).normalized;
        if (UnityEngine.Vector3.Dot(w, nn) < 0) normalMismatch++;
        float cz = (A.z + B.z + C.z) / 3f;
        if (UnityEngine.Mathf.Abs(w.z) < 0.9f) continue;
        if (cz > 6.9f) { if (w.z > 0) northFront++; else northBack++; }
        else if (cz < 3.1f) { if (w.z < 0) southFront++; else southBack++; }
    }
    sb.Append(mesh.name + ": north +Z=" + northFront + " -Z=" + northBack + "; south -Z=" + southFront + " +Z=" + southBack + "; windingVsNormalMismatch=" + normalMismatch + " | ");
}
return sb.ToString();
