// Clearance + provenance audit for the Last Stop presentation prefab.
string prefabPath = "Assets/Resources/Stages/last_stop.prefab";
var sb = new System.Text.StringBuilder();
// Blast corridor from the baked arena (X/Z planes, KO height, top line).
var arena = SlopArena.Shared.ArenaBinaryFormat.LoadFromFile(System.IO.Path.GetFullPath("../../data/arenas/last_stop.arena")).Value;
var lines = SlopArena.Shared.ArenaCollision.ResolveBlastLines(in arena);
var boxMin = new UnityEngine.Vector3(lines.KillMinX, lines.KillHeight, lines.KillMinZ);
var boxMax = new UnityEngine.Vector3(lines.KillMaxX, lines.KillTop, lines.KillMaxZ);
sb.Append("corridor min=" + boxMin + " max=" + boxMax + "; ");

// Separating-axis triangle/AABB overlap (Akenine-Moller).
bool TriBox(UnityEngine.Vector3 c, UnityEngine.Vector3 h, UnityEngine.Vector3 a0, UnityEngine.Vector3 a1, UnityEngine.Vector3 a2)
{
    var v0 = a0 - c; var v1 = a1 - c; var v2 = a2 - c;
    var e = new[] { v1 - v0, v2 - v1, v0 - v2 };
    var axesU = new[] { UnityEngine.Vector3.right, UnityEngine.Vector3.up, UnityEngine.Vector3.forward };
    bool Sep(UnityEngine.Vector3 ax)
    {
        if (ax.sqrMagnitude < 1e-12f) return false;
        float p0 = UnityEngine.Vector3.Dot(v0, ax), p1 = UnityEngine.Vector3.Dot(v1, ax), p2 = UnityEngine.Vector3.Dot(v2, ax);
        float r = h.x * UnityEngine.Mathf.Abs(ax.x) + h.y * UnityEngine.Mathf.Abs(ax.y) + h.z * UnityEngine.Mathf.Abs(ax.z);
        return UnityEngine.Mathf.Min(p0, UnityEngine.Mathf.Min(p1, p2)) > r || UnityEngine.Mathf.Max(p0, UnityEngine.Mathf.Max(p1, p2)) < -r;
    }
    foreach (var u in axesU) foreach (var ed in e) if (Sep(UnityEngine.Vector3.Cross(u, ed))) return false;
    foreach (var u in axesU) if (Sep(u)) return false;
    if (Sep(UnityEngine.Vector3.Cross(e[0], e[1]))) return false;
    return true;
}
var centre = (boxMin + boxMax) * 0.5f; var half = (boxMax - boxMin) * 0.5f;
var contents = UnityEditor.PrefabUtility.LoadPrefabContents(prefabPath);
try
{
    int checkedTris = 0;
    var offenders = new System.Collections.Generic.Dictionary<string, int>();
    foreach (var mf in contents.GetComponentsInChildren<UnityEngine.MeshFilter>(true))
    {
        // The fight shell art matches the collision volumes; everything else is background.
        if (mf.transform.IsChildOf(contents.transform.Find("Shell"))) continue;
        var mesh = mf.sharedMesh; if (mesh == null) continue;
        var m = mf.transform.localToWorldMatrix;
        var b = mf.GetComponent<UnityEngine.Renderer>().bounds;
        if (!b.Intersects(new UnityEngine.Bounds(centre, half * 2f))) continue;
        var v = mesh.vertices; var t = mesh.triangles;
        for (int i = 0; i < t.Length; i += 3)
        {
            checkedTris++;
            if (TriBox(centre, half, m.MultiplyPoint3x4(v[t[i]]), m.MultiplyPoint3x4(v[t[i + 1]]), m.MultiplyPoint3x4(v[t[i + 2]])))
            {
                string key = mf.transform.parent.name + "/" + mf.name;
                offenders[key] = offenders.TryGetValue(key, out int n) ? n + 1 : 1;
            }
        }
    }
    sb.Append("backgroundTrisInBoundsChecked=" + checkedTris + " corridorHits=");
    foreach (var kv in offenders) sb.Append(kv.Key + ":" + kv.Value + " ");
    if (offenders.Count == 0) sb.Append("none");
    sb.Append("; ");
    // Cloud surfaces near the stage must stay under the KO plane.
    float highestCloud = float.MinValue;
    foreach (var mf in contents.transform.Find("World/Clouds").GetComponentsInChildren<UnityEngine.MeshFilter>(true))
    {
        if (mf.name.StartsWith("MistSheets") || mf.name.StartsWith("CloudBase")) continue;
        var m = mf.transform.localToWorldMatrix;
        foreach (var vv in mf.sharedMesh.vertices)
        {
            var w = m.MultiplyPoint3x4(vv);
            if (w.x >= boxMin.x && w.x <= boxMax.x && w.z >= boxMin.z && w.z <= boxMax.z) highestCloud = UnityEngine.Mathf.Max(highestCloud, w.y);
        }
    }
    sb.Append("highestCloudInsideCorridorXZ=" + highestCloud.ToString("F2") + "; ");
}
finally { UnityEditor.PrefabUtility.UnloadPrefabContents(contents); }

// Provenance: every non-script dependency must be stage-owned or a URP/built-in resource.
var foreign = new System.Collections.Generic.List<string>();
int own = 0;
foreach (var dep in UnityEditor.AssetDatabase.GetDependencies(prefabPath, true))
{
    if (dep == prefabPath || dep.EndsWith(".cs")) continue;
    if (dep.StartsWith("Assets/Stages/last_stop/")) { own++; continue; }
    foreign.Add(dep);
}
sb.Append("stageOwnedDeps=" + own + " otherDeps=[" + string.Join(", ", foreign) + "]");
return sb.ToString();

